  ('fab_cotton', 'cotton', 'Cotton', 'Breathable, everyday comfort. Best for day wear and kids.', 0, null, 0, true),
  ('fab_linen', 'linen', 'Linen', 'Cool and textured with a natural crease. Earthy tones only.', 1500, array['ivory','cream','beige','cocoa','maroon','sage','deep-green','navy','terracotta','dusty-rose','sky','white','black','mustard','grey','blush','lilac']::text[], 1, true),
