insert into public.designs (slug, name, category, occasions, description, base_price, fabric_metres, default_fabric, fabric_keys, addon_groups, default_options, featured, badge, id, images, color_images, versions, published, sort) values
  ('blush-leaf-tulle-gown', 'Blush Leaf Tulle Gown', 'bridal', array['Homecoming','Engagement','Party']::text[], 'A strapless satin mini dress with a hand-sculpted leaf appliqué cascading across the bodice, a floor-length tulle overskirt, matching stole and a corset lace-up back.', 24500, 4.5, 'satin', array['satin','silk-blend','crepe']::text[], array['neckline','sleeves','back','lining','embroidery','detail']::text[], array['neck-design','back-corset','lining-full','det-stole']::text[], true, 'Signature', 'des_blush-leaf-tulle-gown', array['/catalog/blush-leaf-tulle-gown/front.webp','/catalog/blush-leaf-tulle-gown/back.webp','/catalog/blush-leaf-tulle-gown/detail.webp','/catalog/blush-leaf-tulle-gown/angle.webp']::text[], '{"purple":["/catalog/blush-leaf-tulle-gown/colours/purple.webp"],"teal":["/catalog/blush-leaf-tulle-gown/colours/teal.webp"],"dusty-rose":["/catalog/blush-leaf-tulle-gown/colours/dusty-rose.webp"],"navy":["/catalog/blush-leaf-tulle-gown/colours/navy.webp"]}'::jsonb, '{}'::text[], true, 0),
  ('noir-sequin-sash-gown', 'Noir Sequin Sash Gown', 'dress', array['Party','Wedding']::text[], 'A fitted V-neck sequin gown on fine straps with a satin waistband and a sweeping side drape that becomes a train at the back. Lace-up corset back.', 32000, 4, 'sequin-net', array['sequin-net','satin','crepe']::text[], array['neckline','sleeves','length','back','lining','embroidery']::text[], array['neck-design','len-design','back-corset','lining-full']::text[], true, 'New', 'des_noir-sequin-sash-gown', array['/catalog/noir-sequin-sash-gown/front.webp','/catalog/noir-sequin-sash-gown/back.webp','/catalog/noir-sequin-sash-gown/detail.webp','/catalog/noir-sequin-sash-gown/angle.webp']::text[], '{"maroon":["/catalog/noir-sequin-sash-gown/colours/maroon.webp"],"emerald":["/catalog/noir-sequin-sash-gown/colours/emerald.webp"],"royal-blue":["/catalog/noir-sequin-sash-gown/colours/royal-blue.webp"],"gold":["/catalog/noir-sequin-sash-gown/colours/gold.webp"]}'::jsonb, '{}'::text[], true, 1),
  ('mauve-lace-drape-saree', 'Mauve Lace Pre-Draped Saree', 'saree-blouse', array['Wedding','Engagement','Festival']::text[], 'A ready-to-wear saree: satin flared skirt and sleeveless V-neck blouse with a floral lace drape stitched in place. No pleating, no pins.', 38500, 6, 'satin', array['satin','silk-blend','crepe']::text[], array['neckline','sleeves','back','lining','embroidery']::text[], array['neck-design','back-zip','lining-full']::text[], true, null, 'des_mauve-lace-drape-saree', array['/catalog/mauve-lace-drape-saree/front.webp','/catalog/mauve-lace-drape-saree/back.webp','/catalog/mauve-lace-drape-saree/detail.webp','/catalog/mauve-lace-drape-saree/angle.webp']::text[], '{"royal-blue":["/catalog/mauve-lace-drape-saree/colours/royal-blue.webp"],"emerald":["/catalog/mauve-lace-drape-saree/colours/emerald.webp"],"red":["/catalog/mauve-lace-drape-saree/colours/red.webp"],"champagne":["/catalog/mauve-lace-drape-saree/colours/champagne.webp"]}'::jsonb, '{}'::text[], true, 2),
  ('maroon-tie-back-column-dress', 'Maroon Tie-Back Column Dress', 'dress', array['Party','Homecoming']::text[], 'A sleek ankle-length column dress with a soft sweetheart neckline, fine straps that cross into long ties and a dramatic open back.', 14500, 3, 'jersey', array['jersey','crepe','satin']::text[], array['neckline','length','back','lining','embroidery','detail','pockets']::text[], array['neck-design','len-design','back-open','lining-half']::text[], true, null, 'des_maroon-tie-back-column-dress', array['/catalog/maroon-tie-back-column-dress/front.webp','/catalog/maroon-tie-back-column-dress/back.webp','/catalog/maroon-tie-back-column-dress/detail.webp','/catalog/maroon-tie-back-column-dress/angle.webp']::text[], '{"maroon":["/catalog/maroon-tie-back-column-dress/front.webp","/catalog/maroon-tie-back-column-dress/back.webp","/catalog/maroon-tie-back-column-dress/detail.webp","/catalog/maroon-tie-back-column-dress/angle.webp","/catalog/maroon-tie-back-column-dress/colours/maroon.webp"],"cream":["/catalog/maroon-tie-back-column-dress/colours/cream.webp"],"sage":["/catalog/maroon-tie-back-column-dress/colours/sage.webp"],"navy":["/catalog/maroon-tie-back-column-dress/colours/navy.webp"]}'::jsonb, '{}'::text[], true, 3),
  ('sage-bloom-lehenga-set', 'Sage Bloom Lehenga Set', 'bridal', array['Wedding','Engagement','Festival']::text[], 'A V-neck crop blouse and flared tulle lehenga skirt covered in hand-placed 3D fabric flowers with beaded vines.', 58000, 7, 'tulle', array['tulle','satin','silk-blend']::text[], array['neckline','sleeves','back','lining','embroidery','detail']::text[], array['neck-design','back-zip','lining-full']::text[], true, 'Bridal', 'des_sage-bloom-lehenga-set', array['/catalog/sage-bloom-lehenga-set/front.webp','/catalog/sage-bloom-lehenga-set/back.webp','/catalog/sage-bloom-lehenga-set/detail.webp','/catalog/sage-bloom-lehenga-set/angle.webp']::text[], '{"maroon":["/catalog/sage-bloom-lehenga-set/colours/maroon.webp"],"ivory":["/catalog/sage-bloom-lehenga-set/colours/ivory.webp"],"mint":["/catalog/sage-bloom-lehenga-set/front.webp","/catalog/sage-bloom-lehenga-set/back.webp","/catalog/sage-bloom-lehenga-set/detail.webp","/catalog/sage-bloom-lehenga-set/angle.webp","/catalog/sage-bloom-lehenga-set/colours/mint.webp"],"navy":["/catalog/sage-bloom-lehenga-set/colours/navy.webp"]}'::jsonb, '{}'::text[], true, 4),
  ('aqua-one-shoulder-cape-gown', 'Aqua One-Shoulder Cape Gown', 'dress', array['Wedding','Party','Engagement']::text[], 'A one-shoulder satin mermaid gown with a beaded bodice, a sheer beaded lace front panel and a floor-sweeping tulle cape.', 42000, 5, 'satin', array['satin','silk-blend','crepe']::text[], array['neckline','length','back','lining','embroidery','detail']::text[], array['neck-design','len-design','back-zip','lining-full']::text[], true, null, 'des_aqua-one-shoulder-cape-gown', array['/catalog/aqua-one-shoulder-cape-gown/front.webp','/catalog/aqua-one-shoulder-cape-gown/back.webp','/catalog/aqua-one-shoulder-cape-gown/detail.webp','/catalog/aqua-one-shoulder-cape-gown/angle.webp']::text[], '{"maroon":["/catalog/aqua-one-shoulder-cape-gown/colours/maroon.webp"],"champagne":["/catalog/aqua-one-shoulder-cape-gown/colours/champagne.webp"],"sage":["/catalog/aqua-one-shoulder-cape-gown/colours/sage.webp"],"navy":["/catalog/aqua-one-shoulder-cape-gown/colours/navy.webp"]}'::jsonb, '{}'::text[], true, 5),
  ('cocoa-tiered-maxi-skirt-set', 'Cocoa Tiered Maxi Skirt Set', 'sets', array['Casual','Office']::text[], 'A three-tier gathered maxi skirt with pockets, a fitted knit tank and a chunky hand-made cardigan. Easy, warm and made to last.', 12500, 3.5, 'linen', array['linen','cotton']::text[], array['length','lining','embroidery','pockets']::text[], array['len-design','lining-none','pockets-side']::text[], true, null, 'des_cocoa-tiered-maxi-skirt-set', array['/catalog/cocoa-tiered-maxi-skirt-set/front.webp','/catalog/cocoa-tiered-maxi-skirt-set/back.webp','/catalog/cocoa-tiered-maxi-skirt-set/detail.webp','/catalog/cocoa-tiered-maxi-skirt-set/angle.webp']::text[], '{"maroon":["/catalog/cocoa-tiered-maxi-skirt-set/colours/maroon.webp"],"cream":["/catalog/cocoa-tiered-maxi-skirt-set/colours/cream.webp"],"sage":["/catalog/cocoa-tiered-maxi-skirt-set/colours/sage.webp"],"navy":["/catalog/cocoa-tiered-maxi-skirt-set/colours/navy.webp"]}'::jsonb, '{}'::text[], true, 6),
  ('little-mal-puff-sleeve-frock', 'Little Mal Puff-Sleeve Frock', 'kids', array['Kids','Party','Festival']::text[], 'A twirly cotton frock with puff sleeves and a waist bow. Sized for ages 2–12.', 7500, 1.8, 'cotton', array['cotton','linen','satin','tulle']::text[], array['neckline','sleeves','length','embroidery','detail','pockets','buttons']::text[], array['neck-design','sleeves-puff','len-design','det-bow']::text[], false, 'Kids', 'des_little-mal-puff-sleeve-frock', '{}'::text[], '{}'::jsonb, '{}'::text[], false, 7),
  ('mal-crochet-crop-top', 'Mal Crochet Crop Top', 'crochet-top', array['Casual','Festival']::text[], 'A hand-crocheted square-neck crop top with flower-motif straps, made by our designer in cotton yarn.', 6500, 0.8, 'crochet-cotton', array['crochet-cotton']::text[], array['sleeves','detail','buttons']::text[], array['sleeves-none']::text[], true, 'Handmade', 'des_mal-crochet-crop-top', '{}'::text[], '{}'::jsonb, '{}'::text[], false, 8),
  ('classic-sweetheart-saree-blouse', 'Classic Sweetheart Saree Blouse', 'saree-blouse', array['Wedding','Festival','Office']::text[], 'A tailored sweetheart saree blouse with elbow sleeves and a gold trim. Bring your saree, we''ll match it.', 5500, 1, 'silk-blend', array['silk-blend','brocade','satin','cotton']::text[], array['neckline','sleeves','back','embroidery','buttons']::text[], array['neck-design','sleeves-elbow','back-buttons']::text[], false, null, 'des_classic-sweetheart-saree-blouse', '{}'::text[], '{}'::jsonb, '{}'::text[], false, 9),
  ('everyday-aline-cotton-frock', 'Everyday A-Line Cotton Frock', 'frock', array['Casual','Office']::text[], 'Our everyday frock: boat neck, cap sleeves, a self belt and an easy A-line midi skirt with pockets.', 8900, 2.8, 'cotton', array['cotton','linen','crepe']::text[], array['neckline','sleeves','length','back','waist','lining','embroidery','buttons','detail','pockets']::text[], array['neck-design','sleeves-cap','len-design','waist-belt','pockets-side']::text[], false, null, 'des_everyday-aline-cotton-frock', '{}'::text[], '{}'::jsonb, '{}'::text[], false, 10),
  ('navy-sequin-fan-party-dress', 'Navy Sequin Fan Party Dress', 'dress', array['Party','Homecoming']::text[], 'A knee-length satin fit-and-flare dress with an asymmetric neckline and a bodice of hand-sewn sequin rays fanning out from the waist. Gathered full skirt, concealed back zip.', 18500, 3.5, 'satin', array['satin','silk-blend','crepe']::text[], array['neckline','sleeves','length','back','lining','embroidery','detail','pockets']::text[], array['neck-design','len-design','back-zip','lining-full']::text[], true, 'New', 'des_navy-sequin-fan-party-dress', array['/catalog/navy-sequin-fan-party-dress/front.webp','/catalog/navy-sequin-fan-party-dress/back.webp','/catalog/navy-sequin-fan-party-dress/detail.webp','/catalog/navy-sequin-fan-party-dress/angle.webp']::text[], '{"navy":["/catalog/navy-sequin-fan-party-dress/front.webp","/catalog/navy-sequin-fan-party-dress/back.webp","/catalog/navy-sequin-fan-party-dress/detail.webp","/catalog/navy-sequin-fan-party-dress/angle.webp","/catalog/navy-sequin-fan-party-dress/colours/navy.webp"],"emerald":["/catalog/navy-sequin-fan-party-dress/colours/emerald.webp"],"blush":["/catalog/navy-sequin-fan-party-dress/colours/blush.webp"],"plum":["/catalog/navy-sequin-fan-party-dress/colours/plum.webp"]}'::jsonb, '{}'::text[], true, 11),
  ('navy-silver-peplum-drape-saree', 'Navy Silver Peplum Drape Saree', 'saree-blouse', array['Wedding','Engagement','Party']::text[], 'A pre-draped saree with a peplum front drape and silver-trimmed pallu over a column skirt embroidered with flowing silver vines. V-neck blouse with sheer puff sleeves and embroidered cuffs.', 42000, 6, 'crepe', array['crepe','silk-blend','satin']::text[], array['neckline','sleeves','back','lining','embroidery','detail']::text[], array['neck-design','sleeves-puff','back-zip','lining-full']::text[], true, 'New', 'des_navy-silver-peplum-drape-saree', array['/catalog/navy-silver-peplum-drape-saree/front.webp','/catalog/navy-silver-peplum-drape-saree/back.webp','/catalog/navy-silver-peplum-drape-saree/detail.webp','/catalog/navy-silver-peplum-drape-saree/angle.webp']::text[], '{"navy":["/catalog/navy-silver-peplum-drape-saree/front.webp","/catalog/navy-silver-peplum-drape-saree/back.webp","/catalog/navy-silver-peplum-drape-saree/detail.webp","/catalog/navy-silver-peplum-drape-saree/angle.webp","/catalog/navy-silver-peplum-drape-saree/colours/navy.webp"],"emerald":["/catalog/navy-silver-peplum-drape-saree/colours/emerald.webp"],"rose-pink":["/catalog/navy-silver-peplum-drape-saree/colours/rose-pink.webp"],"ivory":["/catalog/navy-silver-peplum-drape-saree/colours/ivory.webp"]}'::jsonb, '{}'::text[], true, 12),
  ('champagne-lace-high-neck-saree', 'Champagne Lace High-Neck Saree', 'bridal', array['Wedding','Engagement']::text[], 'A soft net saree covered in gold-thread floral embroidery with a scalloped lace border, worn with a sleeveless high-neck sheer lace blouse.', 46000, 6.5, 'tulle', array['tulle','silk-blend','satin']::text[], array['neckline','sleeves','back','lining','embroidery','buttons']::text[], array['neck-design','sleeves-none','back-buttons','lining-half']::text[], true, 'Bridal', 'des_champagne-lace-high-neck-saree', array['/catalog/champagne-lace-high-neck-saree/front.webp','/catalog/champagne-lace-high-neck-saree/back.webp','/catalog/champagne-lace-high-neck-saree/detail.webp','/catalog/champagne-lace-high-neck-saree/angle.webp']::text[], '{"champagne":["/catalog/champagne-lace-high-neck-saree/front.webp","/catalog/champagne-lace-high-neck-saree/back.webp","/catalog/champagne-lace-high-neck-saree/detail.webp","/catalog/champagne-lace-high-neck-saree/angle.webp","/catalog/champagne-lace-high-neck-saree/colours/champagne.webp"],"lilac":["/catalog/champagne-lace-high-neck-saree/colours/lilac.webp"],"blush":["/catalog/champagne-lace-high-neck-saree/colours/blush.webp"],"mint":["/catalog/champagne-lace-high-neck-saree/colours/mint.webp"]}'::jsonb, '{}'::text[], true, 13),
  ('cocoa-linen-peplum-top', 'Cocoa Linen Peplum Top', 'sets', array['Office','Casual']::text[], 'A sleeveless boat-neck linen top with a fitted bodice and a box-pleated peplum. Back zip. Lovely with wide-leg trousers — ask us to make a matching pair.', 6900, 1.4, 'linen', array['linen','cotton','crepe']::text[], array['neckline','sleeves','lining','embroidery','buttons']::text[], array['neck-design','sleeves-none','lining-none']::text[], false, null, 'des_cocoa-linen-peplum-top', array['/catalog/cocoa-linen-peplum-top/front.webp','/catalog/cocoa-linen-peplum-top/back.webp','/catalog/cocoa-linen-peplum-top/detail.webp','/catalog/cocoa-linen-peplum-top/angle.webp']::text[], '{"sage":["/catalog/cocoa-linen-peplum-top/colours/sage.webp"],"blush":["/catalog/cocoa-linen-peplum-top/colours/blush.webp"],"lilac":["/catalog/cocoa-linen-peplum-top/colours/lilac.webp"],"sky":["/catalog/cocoa-linen-peplum-top/colours/sky.webp"]}'::jsonb, '{}'::text[], true, 14),
