  ('lilac-ruffle-saree', 'Lilac Ruffle Saree', 'saree-blouse', array['Wedding','Festival','Office']::text[], 'A soft textured saree edged with frills along the pallu and hem, paired with a long-sleeve sheer lace blouse in a deeper lilac.', 28500, 6, 'cotton', array['cotton','crepe','silk-blend']::text[], array['neckline','sleeves','back','lining','embroidery']::text[], array['neck-design','sleeves-long','back-zip','lining-half']::text[], false, null, 'des_lilac-ruffle-saree', array['/catalog/lilac-ruffle-saree/front.webp','/catalog/lilac-ruffle-saree/back.webp','/catalog/lilac-ruffle-saree/detail.webp','/catalog/lilac-ruffle-saree/angle.webp']::text[], '{"lilac":["/catalog/lilac-ruffle-saree/front.webp","/catalog/lilac-ruffle-saree/back.webp","/catalog/lilac-ruffle-saree/detail.webp","/catalog/lilac-ruffle-saree/angle.webp","/catalog/lilac-ruffle-saree/colours/lilac.webp"],"ivory":["/catalog/lilac-ruffle-saree/colours/ivory.webp"],"sage":["/catalog/lilac-ruffle-saree/colours/sage.webp"],"dusty-rose":["/catalog/lilac-ruffle-saree/colours/dusty-rose.webp"]}'::jsonb, '{}'::text[], true, 16),
  ('satin-halter-a-line-gown', 'Satin Halter A-Line Gown', 'dress', array['Wedding','Party','Engagement']::text[], 'A floor-length satin gown with a sweetheart halter neckline, fitted bodice and a fluid A-line skirt. Shown in wine, champagne, sage and navy.', 19500, 5, 'satin', array['satin','silk-blend','crepe']::text[], array['length','back','lining','pockets']::text[], array['len-design','back-zip','lining-full']::text[], true, '4 colours', 'des_satin-halter-a-line-gown', array['/catalog/satin-halter-a-line-gown/colours/maroon.webp','/catalog/satin-halter-a-line-gown/colours/champagne.webp','/catalog/satin-halter-a-line-gown/colours/sage.webp','/catalog/satin-halter-a-line-gown/colours/navy.webp']::text[], '{"maroon":["/catalog/satin-halter-a-line-gown/colours/maroon.webp"],"champagne":["/catalog/satin-halter-a-line-gown/colours/champagne.webp"],"sage":["/catalog/satin-halter-a-line-gown/colours/sage.webp"],"navy":["/catalog/satin-halter-a-line-gown/colours/navy.webp"]}'::jsonb, '{}'::text[], true, 17),
  ('pleated-midi-dress', 'Pleated Midi Dress', 'dress', array['Party','Office','Engagement']::text[], 'A fitted bodice with princess seams and a full box-pleated midi skirt with pockets. Choose the neckline: high-neck halter, folded off-shoulder or V-wrap halter. Concealed back zip.', 13500, 3.8, 'crepe', array['crepe','satin','linen','cotton']::text[], array['length','lining','pockets']::text[], array['len-design','lining-half','pockets-side']::text[], true, '3 necklines', 'des_pleated-midi-dress', array['/catalog/pleated-midi-dress/high-neck-halter/front.webp','/catalog/pleated-midi-dress/high-neck-halter/back.webp','/catalog/pleated-midi-dress/high-neck-halter/detail.webp','/catalog/pleated-midi-dress/high-neck-halter/angle.webp']::text[], '{"navy":["/catalog/pleated-midi-dress/high-neck-halter/front.webp","/catalog/pleated-midi-dress/high-neck-halter/back.webp","/catalog/pleated-midi-dress/high-neck-halter/detail.webp","/catalog/pleated-midi-dress/high-neck-halter/angle.webp","/catalog/pleated-midi-dress/colours/navy.webp"],"sage":["/catalog/pleated-midi-dress/colours/sage.webp"],"dusty-rose":["/catalog/pleated-midi-dress/colours/dusty-rose.webp"],"lavender":["/catalog/pleated-midi-dress/colours/lavender.webp"]}'::jsonb, array['{"key":"off-shoulder-fold","name":"Off-shoulder fold","price":1500,"images":["/catalog/pleated-midi-dress/off-shoulder-fold/front.webp","/catalog/pleated-midi-dress/off-shoulder-fold/back.webp","/catalog/pleated-midi-dress/off-shoulder-fold/detail.webp","/catalog/pleated-midi-dress/off-shoulder-fold/angle.webp"],"color_images":{"black":["/catalog/pleated-midi-dress/off-shoulder-fold/colours/black.webp"],"navy":["/catalog/pleated-midi-dress/off-shoulder-fold/front.webp","/catalog/pleated-midi-dress/off-shoulder-fold/back.webp","/catalog/pleated-midi-dress/off-shoulder-fold/detail.webp","/catalog/pleated-midi-dress/off-shoulder-fold/angle.webp","/catalog/pleated-midi-dress/off-shoulder-fold/colours/navy.webp"],"dusty-rose":["/catalog/pleate