  ('blush-draped-chiffon-gown', 'Blush Draped Chiffon Gown', 'dress', array['Wedding','Engagement','Party']::text[], 'A floor-length chiffon gown with a soft cowl neckline, cap-sleeve shoulder straps and a fitted bodice. Fabric is gathered at the hip and falls in a cascading side drape.', 21500, 5.5, 'chiffon', array['chiffon','satin','silk-blend','crepe']::text[], array['length','back','lining']::text[], array['len-design','back-zip','lining-full']::text[], true, 'New', 'des_blush-draped-chiffon-gown', array['/catalog/blush-draped-chiffon-gown/front.webp','/catalog/blush-draped-chiffon-gown/back.webp','/catalog/blush-draped-chiffon-gown/detail.webp','/catalog/blush-draped-chiffon-gown/angle.webp']::text[], '{}'::jsonb, '{}'::text[], true, 19),
  ('pearl-organza-midi-dress', 'Pearl Organza Midi Dress', 'dress', array['Homecoming','Party','Engagement']::text[], 'A strapless organza midi with a structured bodice and a full, layered A-line skirt, finished with hand-sewn pearls scattered across the bodice and skirt.', 18500, 4.5, 'organza', array['organza','tulle','satin']::text[], array['length','back','lining']::text[], array['len-design','back-zip','lining-full']::text[], true, 'New', 'des_pearl-organza-midi-dress', array['/catalog/pearl-organza-midi-dress/front.webp','/catalog/pearl-organza-midi-dress/back.webp','/catalog/pearl-organza-midi-dress/detail.webp','/catalog/pearl-organza-midi-dress/angle.webp']::text[], '{}'::jsonb, '{}'::text[], true, 20),
  ('satin-capelet-wrap-gown', 'Satin Capelet Wrap Gown', 'dress', array['Wedding','Engagement','Party']::text[], 'A two-piece in liquid satin: a boat-neck capelet that falls past the elbows, over a draped wrap skirt with a high front slit and a soft sweep. Shown in ivory, blush, mint and lavender.', 23500, 5.5, 'satin', array['satin','silk-blend','crepe']::text[], array['length','lining']::text[], array['len-design','lining-full']::text[], true, 'New', 'des_satin-capelet-wrap-gown', array['/catalog/satin-capelet-wrap-gown/colours/ivory.webp','/catalog/satin-capelet-wrap-gown/colours/blush.webp','/catalog/satin-capelet-wrap-gown/colours/mint.webp','/catalog/satin-capelet-wrap-gown/colours/lavender.webp']::text[], '{"ivory":["/catalog/satin-capelet-wrap-gown/colours/ivory.webp"],"blush":["/catalog/satin-capelet-wrap-gown/colours/blush.webp"],"mint":["/catalog/satin-capelet-wrap-gown/colours/mint.webp"],"lavender":["/catalog/satin-capelet-wrap-gown/colours/lavender.webp"]}'::jsonb, '{}'::text[], true, 21)
